WITH t AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin) SELECT $1,'M9-TPARENT2', min(milestone_id), 9993, 'подсадка самотеста', 'S', 'not_started', 'dev', 'declared' FROM project_plan_tasks WHERE project_id=$1 RETURNING id, milestone_id), r AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin, parent_task_id) SELECT $1,'M9-TRED2', t.milestone_id, 9992, 'красная проба', 'S', 'not_started', 'red', 'declared', t.id FROM t RETURNING id) INSERT INTO project_task_check(project_id, task_id, check_id, said_as) SELECT $1, 'M9-TPARENT2', 'TC-PROBE-77', 'доказательство' FROM r
